	scwin.setOffset = function() {
		window.init_offset = WebSquare.wUnit.getDomById('windowContainer1_nameLayer_mf_windowContainer1_subWindow17').getBoundingClientRect().right;
	}		
	scwin.checkVal = function() {
		const changed_offset  = WebSquare.wUnit.getDomById('windowContainer1_nameLayer_mf_windowContainer1_subWindow17').getBoundingClientRect().right
		//const elem_width  = WebSquare.wUnit.getDomById('mf_windowContainer1_nameLayer_mf_windowContainer1_subWindow17').offsetWidth
		console.log('window.init_offset : '+ window.init_offset)
		console.log('changed_offset : '+ changed_offset)
		return window.init_offset != changed_offset;
	}		

	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("set", "scwin.setOffset()");
		WebSquare.wUnit.addCommand("pause", "500");

		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('windowContainer1_left').click()");
